mapper.select:
SELECT COUNT(*)
FROM BOK_SCHEME_INFO A
WHERE A.SCH_NAME = #{schemeName}

SELECT A.SCHEME_ID schemeId,
       B.SCH_NAME schemeName
FROM BOK_BOOKSET_PLAN A
LEFT JOIN BOK_SCHEME_INFO B
    ON B.SCH_ID = A.SCHEME_ID
WHERE A.SCHEME_TYPE = #{schemeType}
    AND A.BOOKSET_ID = #{booksetId}
    AND B.IS_DEFAULT = 'Y'

    AND A.SCHEME_ID != #{schemeId}

SELECT COUNT(*)
FROM BOK_BOOKSET_PLAN A
LEFT JOIN BOK_SCHEME_INFO B
    ON B.SCH_ID = A.SCHEME_ID
WHERE B.SCHEME_TYPE = #{schemeType}
    AND A.BOOKSET_ID = #{booksetId}
